___CSS_LOADER_EXPORT___.push([module.id, "\n.toggle-button {\n    position: fixed;\n    top: 35%;\n    right: -105px;\n    transform: translateY(-50%) rotate(-90deg);\n    transform-origin: center;\n    background-color: rgba(115, 183, 255, 0.6);\n    color: white;\n    padding: 5px 10px;\n    cursor: pointer;\n    border-radius: 5px;\n    z-index: 1;\n    transition: all 0.3s ease-in-out;\n    font-weight: 400;\n    font-size: 16px;\n    line-height: 1;\n    display: block;\n    height: auto;\n    width: 230px !important;\n    border: none;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    text-align: center;\n}\n.toggle-button:hover {\n    background-color: rgba(0, 123, 255, 0.8);\n    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);\n}\n.toggle-button.shift {\n    right: 300px !important;\n    background-color: rgba(0, 123, 255, 0.8);\n    z-index: 1023;\n}\n.additional-information {\n    position: fixed;\n    display: flex;\n    flex-direction: column;\n    padding-left: 20px;\n    padding-right: 20px;\n    top: 0;\n    right: -100%;\n    height: 100%;\n    width: 400px;\n    background-color: #f9f9f9;\n    box-shadow: -2px 0 5px rgba(0, 0, 0, 0.1);\n    transition: right 0.3s ease-in-out;\n    overflow-y: auto;\n    z-index: 1022;\n}\n.additional-information.show {\n    right: 0;\n}\n.content-opacity {\n    position: relative;\n}\n.content-opacity::after {\n    content: \"\";\n    position: fixed;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    background-color: rgba(0, 0, 0, 0.5);\n    z-index: 1021;\n}\n@media only screen and (max-width: 920px) {\n.head-notes .dates {\n        display: flex;\n        flex-direction: column;\n}\n.head-notes .dates .issue-date,\n    .head-notes .dates .expiration-date,\n    .head-notes .dates .delivery-date {\n        width: 90% !important;\n}\n}\n@media only screen and (max-width: 768px) {\nheader .head-notes {\n        display: flex;\n        flex-direction: column;\n        justify-content: start;\n}\n.head-notes .dates {\n        margin-left: 0px !important;\n}\n.head-notes .dates .issue-date,\n    .head-notes .dates .expiration-date,\n    .head-notes .dates .delivery-date {\n        width: 100% !important;\n}\n}\n@media only screen and (max-width: 460px) {\n.additional-information {\n        width: 80%;\n}\n.toggle-button.shift {\n        right: 58% !important;\n}\n}\n", "",{"version":3,"sources":["webpack://./modules/Sale/Resources/assets/js/views/contracts/form.vue"],"names":[],"mappings":";AAsxBA;IACA,eAAA;IACA,QAAA;IACA,aAAA;IACA,0CAAA;IACA,wBAAA;IACA,0CAAA;IACA,YAAA;IACA,iBAAA;IACA,eAAA;IACA,kBAAA;IACA,UAAA;IACA,gCAAA;IACA,gBAAA;IACA,eAAA;IACA,cAAA;IACA,cAAA;IACA,YAAA;IACA,uBAAA;IACA,YAAA;IACA,mBAAA;IACA,gBAAA;IACA,uBAAA;IACA,kBAAA;AACA;AACA;IACA,wCAAA;IACA,yCAAA;AACA;AACA;IACA,uBAAA;IACA,wCAAA;IACA,aAAA;AACA;AACA;IACA,eAAA;IACA,aAAA;IACA,sBAAA;IACA,kBAAA;IACA,mBAAA;IACA,MAAA;IACA,YAAA;IACA,YAAA;IACA,YAAA;IACA,yBAAA;IACA,yCAAA;IACA,kCAAA;IACA,gBAAA;IACA,aAAA;AACA;AACA;IACA,QAAA;AACA;AACA;IACA,kBAAA;AACA;AACA;IACA,WAAA;IACA,eAAA;IACA,MAAA;IACA,OAAA;IACA,WAAA;IACA,YAAA;IACA,oCAAA;IACA,aAAA;AACA;AACA;AACA;QACA,aAAA;QACA,sBAAA;AACA;AACA;;;QAGA,qBAAA;AACA;AACA;AACA;AACA;QACA,aAAA;QACA,sBAAA;QACA,sBAAA;AACA;AACA;QACA,2BAAA;AACA;AACA;;;QAGA,sBAAA;AACA;AACA;AACA;AACA;QACA,UAAA;AACA;AACA;QACA,qBAAA;AACA;AACA","sourcesContent":["<template>\n    <div\n        class=\"card mb-0 pt-2 pt-md-0\"\n        :class=\"{ 'content-opacity': isVisible }\"\n        @click.self=\"toggleInformation\"\n    >\n        <!-- <div class=\"card-header bg-info\">\n            <h3 class=\"my-0\">Nuevo Comprobante</h3>\n        </div> -->\n        <div\n            class=\"tab-content tab-content-default row-new\"\n            v-if=\"loading_form\"\n        >\n            <div class=\"invoice p-0\">\n                <header class=\"clearfix clearfix-default p-2\">\n                    <div class=\"d-flex head-notes\">\n                        <div\n                            class=\"col-sm-2 text-center mt-3 mb-0\"\n                            style=\"margin-right: auto;\"\n                        >\n                        <logo \n                            url=\"/\"\n                            :path_logo=\"getCurrentLogo\"\n                        ></logo>\n                        </div>\n                        <div class=\"text-left mt-3 mb-0\">\n                            <address class=\"ib mr-2\">\n                                <span class=\"font-weight-bold d-block\"\n                                    >CONTRATO</span\n                                >\n                                <!-- <span class=\"font-weight-bold d-block\">CNT-XXX</span> -->\n                                <span class=\"font-weight-bold\">{{\n                                    company.name\n                                }}</span>\n                                <br />\n                                <div v-if=\"establishment.address != '-'\">\n                                    {{ establishment.address }},\n                                </div>\n                                {{ establishment.district.description }},\n                                {{ establishment.province.description }},\n                                {{ establishment.department.description }} -\n                                {{ establishment.country.description }}\n                                <br />\n                                {{ establishment.email }} -\n                                <span v-if=\"establishment.telephone != '-'\">{{\n                                    establishment.telephone\n                                }}</span>\n                            </address>\n                        </div>\n                        <!-- <div class=\"col-sm-4\"> -->\n                        <!-- <el-checkbox class=\"mt-3\" v-model=\"form.active_terms_condition\" @change=\"changeTermsCondition\">Términos y condiciones del contrato</el-checkbox> -->\n                        <!-- </div> -->\n\n                        <div\n                            class=\"d-flex align-items-center justify-content-end dates\"\n                            style=\"margin-left: auto; width: auto;\"\n                        >\n                            <div class=\"p-1 issue-date\" style=\"width: 30%;\">\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.date_of_issue\n                                    }\"\n                                >\n                                    <!--<label class=\"control-label\">Fecha de emisión</label>-->\n                                    <label class=\"control-label\"\n                                        >Fec. Emisión</label\n                                    >\n                                    <el-date-picker\n                                        v-model=\"form.date_of_issue\"\n                                        type=\"date\"\n                                        value-format=\"yyyy-MM-dd\"\n                                        :clearable=\"false\"\n                                        @change=\"changeDateOfIssue\"\n                                    ></el-date-picker>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.date_of_issue\"\n                                        v-text=\"errors.date_of_issue[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n                            <div\n                                class=\"p-1 expiration-date\"\n                                style=\"width: 30%;\"\n                            >\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.date_of_due\n                                    }\"\n                                >\n                                    <label class=\"control-label\"\n                                        >Fec. Vencimiento</label\n                                    >\n                                    <el-date-picker\n                                        v-model=\"form.date_of_due\"\n                                        type=\"date\"\n                                        value-format=\"yyyy-MM-dd\"\n                                        :clearable=\"true\"\n                                    ></el-date-picker>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.date_of_due\"\n                                        v-text=\"errors.date_of_due[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n                            <div class=\"p-1 delivery-date\" style=\"width: 30%;\">\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.delivery_date\n                                    }\"\n                                >\n                                    <label class=\"control-label\"\n                                        >Fec. Entrega\n                                        <el-tooltip\n                                            class=\"item\"\n                                            effect=\"dark\"\n                                            content=\"Fecha de entrega de proyecto\"\n                                            placement=\"top-end\"\n                                        >\n                                            <i class=\"fa fa-info-circle\"></i>\n                                        </el-tooltip>\n                                    </label>\n                                    <el-date-picker\n                                        v-model=\"form.delivery_date\"\n                                        type=\"date\"\n                                        value-format=\"yyyy-MM-dd\"\n                                        :clearable=\"true\"\n                                    ></el-date-picker>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.delivery_date\"\n                                        v-text=\"errors.delivery_date[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </header>\n                <form autocomplete=\"off\" @submit.prevent=\"submit\">\n                    <div class=\"form-body m-4\">\n                        <div class=\"row mt-1\">\n                            <div class=\"col-lg-6 pb-2\">\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.customer_id\n                                    }\"\n                                >\n                                    <label\n                                        class=\"control-label font-weight-bold text-info\"\n                                    >\n                                        Cliente\n                                        <a\n                                            href=\"#\"\n                                            @click.prevent=\"\n                                                showDialogNewPerson = true\n                                            \"\n                                            >[+ Nuevo]</a\n                                        >\n                                    </label>\n                                    <el-select\n                                        v-model=\"form.customer_id\"\n                                        filterable\n                                        remote\n                                        class=\"border-left rounded-left border-info\"\n                                        popper-class=\"el-select-customers\"\n                                        dusk=\"customer_id\"\n                                        placeholder=\"Escriba el nombre o número de documento del cliente\"\n                                        :remote-method=\"searchRemoteCustomers\"\n                                        :loading=\"loading_search\"\n                                        @keyup.enter.native=\"keyupCustomer\"\n                                    >\n                                        <el-option\n                                            v-for=\"option in customers\"\n                                            :key=\"option.id\"\n                                            :value=\"option.id\"\n                                            :label=\"option.description\"\n                                        ></el-option>\n                                    </el-select>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.customer_id\"\n                                        v-text=\"errors.customer_id[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n\n                            <div class=\"col-lg-2\">\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger':\n                                            errors.payment_method_type_id\n                                    }\"\n                                >\n                                    <label class=\"control-label\">\n                                        Término de pago\n                                    </label>\n                                    <el-select\n                                        v-model=\"form.payment_method_type_id\"\n                                        filterable\n                                        @change=\"changePaymentMethodType\"\n                                    >\n                                        <el-option\n                                            v-for=\"option in payment_method_types\"\n                                            :key=\"option.id\"\n                                            :value=\"option.id\"\n                                            :label=\"option.description\"\n                                        ></el-option>\n                                    </el-select>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.payment_method_type_id\"\n                                        v-text=\"\n                                            errors.payment_method_type_id[0]\n                                        \"\n                                    ></small>\n                                </div>\n                            </div>\n                            <div class=\"col-lg-2\">\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.currency_type_id\n                                    }\"\n                                >\n                                    <label class=\"control-label\">Moneda</label>\n                                    <el-select\n                                        v-model=\"form.currency_type_id\"\n                                        @change=\"changeCurrencyType\"\n                                    >\n                                        <el-option\n                                            v-for=\"option in currency_types\"\n                                            :key=\"option.id\"\n                                            :value=\"option.id\"\n                                            :label=\"option.description\"\n                                        ></el-option>\n                                    </el-select>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.currency_type_id\"\n                                        v-text=\"errors.currency_type_id[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n                            <div class=\"col-lg-2\">\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.exchange_rate_sale\n                                    }\"\n                                >\n                                    <label class=\"control-label\"\n                                        >Tipo de cambio\n                                        <el-tooltip\n                                            class=\"item\"\n                                            effect=\"dark\"\n                                            content=\"Tipo de cambio del día, extraído de SUNAT\"\n                                            placement=\"top-end\"\n                                        >\n                                            <i class=\"fa fa-info-circle\"></i>\n                                        </el-tooltip>\n                                    </label>\n                                    <el-input\n                                        v-model=\"form.exchange_rate_sale\"\n                                    ></el-input>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.exchange_rate_sale\"\n                                        v-text=\"errors.exchange_rate_sale[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- Información Adicional -->\n                        <div>\n                            <!-- Botón para mostrar/ocultar el componente -->\n                            <span\n                                class=\"toggle-button toggle-button-orders\"\n                                :class=\"{ shift: isVisible }\"\n                                @click=\"toggleInformation\"\n                                :title=\"isVisible ? 'Cerrar Información Adicional' : 'Abrir Información Adicional'\"\n                            >\n                                <span class=\"toggle-button-text\">\n                                    {{\n                                        isVisible\n                                            ? \"Cerrar Información Adicional\"\n                                            : \"Abrir Información Adicional\"\n                                    }}\n                                </span>\n                            </span>\n\n                            <div\n                                class=\"additional-information\"\n                                :class=\"{ show: isVisible }\"\n                            >\n                                <h3 class=\"text-center\">\n                                    Información Adicional\n                                </h3>\n\n                                <div class=\"close-container\">\n                                    <i class=\"el-icon el-icon-close\"\n                                        @click=\"toggleInformation\">\n                                    </i>\n                                </div>\n\n                                <div class=\"form-group\">\n                                    <label class=\"control-label\"\n                                        >Vendedor</label\n                                    >\n                                    <el-select\n                                        v-model=\"form.seller_id\"\n                                        clearable\n                                    >\n                                        <el-option\n                                            v-for=\"sel in sellers\"\n                                            :key=\"sel.id\"\n                                            :value=\"sel.id\"\n                                            :label=\"sel.name\"\n                                            >{{ sel.name }}\n                                        </el-option>\n                                    </el-select>\n                                </div>\n\n                                <div class=\"\">\n                                    <div\n                                        class=\"form-group\"\n                                        :class=\"{\n                                            'has-danger':\n                                                errors.exchange_rate_sale\n                                        }\"\n                                    >\n                                        <label class=\"control-label\"\n                                            >Descripcion</label\n                                        >\n                                        <el-input\n                                            type=\"textarea\"\n                                            :rows=\"3\"\n                                            v-model=\"form.description\"\n                                        ></el-input>\n                                        <small\n                                            class=\"form-control-feedback\"\n                                            v-if=\"errors.description\"\n                                            v-text=\"errors.description[0]\"\n                                        ></small>\n                                    </div>\n                                </div>\n\n                                <div class=\"form-group\">\n                                    <label class=\"control-label\"\n                                        >Número de cuenta\n                                    </label>\n                                    <el-input\n                                        v-model=\"form.account_number\"\n                                    ></el-input>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.account_number\"\n                                        v-text=\"errors.account_number[0]\"\n                                    ></small>\n                                </div>\n\n                                <div class=\"form-group\">\n                                    <label class=\"control-label\"\n                                        >Dirección de envío\n                                    </label>\n                                    <el-input\n                                        v-model=\"form.shipping_address\"\n                                    ></el-input>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.shipping_address\"\n                                        v-text=\"errors.shipping_address[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n                        </div>\n                        <!-- Fin informacion adicional -->\n\n                        <div class=\"row mt-3\">\n                            <div class=\"col-md-12\">\n                                <div class=\"table-responsive\">\n                                    <table class=\"table mb-1\">\n                                        <thead>\n                                            <tr class=\"table-titles-default\">\n                                                <th width=\"0.5%\"><!--#--></th>\n                                                <th\n                                                    class=\"font-weight-bold\"\n                                                    width=\"30%\"\n                                                >\n                                                    Descripción\n                                                </th>\n                                                <th\n                                                    width=\"8%\"\n                                                    class=\"text-center font-weight-bold\"\n                                                >\n                                                    Unidad\n                                                </th>\n                                                <th\n                                                    width=\"8%\"\n                                                    class=\"text-center font-weight-bold\"\n                                                >\n                                                    Cantidad\n                                                </th>\n                                                <th\n                                                    class=\"text-center font-weight-bold\"\n                                                >\n                                                    Valor Unitario\n                                                </th>\n                                                <th\n                                                    class=\"text-center font-weight-bold\"\n                                                >\n                                                    Precio Unitario\n                                                </th>\n                                                <th\n                                                    class=\"text-center font-weight-bold\"\n                                                >\n                                                    Subtotal\n                                                </th>\n                                                <!--<th class=\"text-right font-weight-bold\">Cargo</th>-->\n                                                <th\n                                                    class=\"text-center font-weight-bold\"\n                                                >\n                                                    Total\n                                                </th>\n                                                <th width=\"8%\"></th>\n                                            </tr>\n                                        </thead>\n                                        <tbody v-if=\"form.items.length > 0\">\n                                            <tr\n                                                v-for=\"(row,\n                                                index) in form.items\"\n                                                :key=\"index\"\n                                            >\n                                                <td><!--{{ index + 1 }}--></td>\n                                                <td>\n                                                    {{\n                                                        setDescriptionOfItem(\n                                                            row.item\n                                                        )\n                                                    }}\n                                                    {{\n                                                        row.item.presentation.hasOwnProperty(\n                                                            \"description\"\n                                                        )\n                                                            ? row.item\n                                                                  .presentation\n                                                                  .description\n                                                            : \"\"\n                                                    }}<br /><small>{{\n                                                        row.affectation_igv_type\n                                                            .description\n                                                    }}</small>\n                                                </td>\n                                                <!-- <td>{{row.item.description}} {{row.item.presentation.hasOwnProperty('description') ? row.item.presentation.description : ''}}<br/><small>{{row.affectation_igv_type.description}}</small></td> -->\n                                                <td class=\"text-center\">\n                                                    {{ row.item.unit_type_id }}\n                                                </td>\n                                                <td class=\"text-center\">\n                                                    {{ row.quantity }}\n                                                </td>\n                                                <!-- <td class=\"text-right\">{{currency_type.symbol}} {{row.unit_price}}</td> -->\n                                                <td class=\"text-center\">\n                                                    {{ currency_type.symbol }}\n                                                    {{\n                                                        getFormatUnitPriceRow(\n                                                            row.unit_value\n                                                        )\n                                                    }}\n                                                </td>\n                                                <td class=\"text-center\">\n                                                    {{ currency_type.symbol }}\n                                                    {{\n                                                        getFormatUnitPriceRow(\n                                                            row.unit_price\n                                                        )\n                                                    }}\n                                                </td>\n\n                                                <td class=\"text-center\">\n                                                    {{ currency_type.symbol }}\n                                                    {{ row.total_value }}\n                                                </td>\n                                                <!--<td class=\"text-right\">{{ currency_type.symbol }} {{ row.total_charge }}</td>-->\n                                                <td class=\"text-center\">\n                                                    {{ currency_type.symbol }}\n                                                    {{ row.total }}\n                                                </td>\n                                                <td class=\"text-center\">\n                                                    <button\n                                                        type=\"button\"\n                                                        class=\"btn waves-effect waves-light btn-xs btn-danger\"\n                                                        @click.prevent=\"\n                                                            clickRemoveItem(\n                                                                index\n                                                            )\n                                                        \"\n                                                    >\n                                                        x\n                                                    </button>\n                                                </td>\n                                            </tr>\n                                            <!-- <tr>\n                                            <td colspan=\"9\"></td>\n                                        </tr> -->\n                                        </tbody>\n                                    </table>\n                                </div>\n                            </div>\n                            <div\n                                class=\"col-lg-12 col-md-6 d-flex flex-column align-items-start mt-1\"\n                            >\n                                <div class=\"pb-2\">\n                                    <button\n                                        type=\"button\"\n                                        class=\"btn waves-effect waves-light btn-primary\"\n                                        @click.prevent=\"\n                                            showDialogAddItem = true\n                                        \"\n                                    >\n                                        + Agregar Producto\n                                    </button>\n                                </div>\n                                <div\n                                    v-if=\"form.items.length > 0\"\n                                    class=\"total-rows\"\n                                >\n                                    <span\n                                        >Total de ítems:\n                                        {{ form.items.length }}</span\n                                    >\n                                </div>\n                            </div>\n\n                            <div class=\"col-md-8 mt-3\"></div>\n\n                            <div class=\"col-md-4\">\n                                <p\n                                    class=\"text-right\"\n                                    v-if=\"form.total_exportation > 0\"\n                                >\n                                    OP.EXPORTACIÓN: {{ currency_type.symbol }}\n                                    {{ form.total_exportation }}\n                                </p>\n                                <p\n                                    class=\"text-right\"\n                                    v-if=\"form.total_free > 0\"\n                                >\n                                    OP.GRATUITAS: {{ currency_type.symbol }}\n                                    {{ form.total_free }}\n                                </p>\n                                <p\n                                    class=\"text-right\"\n                                    v-if=\"form.total_unaffected > 0\"\n                                >\n                                    OP.INAFECTAS: {{ currency_type.symbol }}\n                                    {{ form.total_unaffected }}\n                                </p>\n                                <p\n                                    class=\"text-right\"\n                                    v-if=\"form.total_exonerated > 0\"\n                                >\n                                    OP.EXONERADAS: {{ currency_type.symbol }}\n                                    {{ form.total_exonerated }}\n                                </p>\n                                <p\n                                    class=\"text-right\"\n                                    v-if=\"form.total_taxed > 0\"\n                                >\n                                    OP.GRAVADA: {{ currency_type.symbol }}\n                                    {{ form.total_taxed }}\n                                </p>\n                                <p class=\"text-right\" v-if=\"form.total_igv > 0\">\n                                    IGV: {{ currency_type.symbol }}\n                                    {{ form.total_igv }}\n                                </p>\n                                <h3 class=\"text-right\" v-if=\"form.total > 0\">\n                                    <b>TOTAL A PAGAR: </b\n                                    >{{ currency_type.symbol }} {{ form.total }}\n                                </h3>\n                            </div>\n\n                            <!-- pago -->\n                            <div style=\"margin-left: auto;\">\n                                <div\n                                    class=\"p-2 payment-container\"\n                                    v-if=\"showPayments && !form.quotation_id\"\n                                >\n                                    <table>\n                                        <thead>\n                                            <tr width=\"100%\">\n                                                <th\n                                                    v-if=\"\n                                                        form.payments.length > 0\n                                                    \"\n                                                    class=\"pb-2\"\n                                                >\n                                                    Método de pago\n                                                </th>\n                                                <th\n                                                    v-if=\"\n                                                        form.payments.length > 0\n                                                    \"\n                                                    class=\"pb-2\"\n                                                >\n                                                    Destino\n                                                </th>\n                                                <th\n                                                    v-if=\"\n                                                        form.payments.length > 0\n                                                    \"\n                                                    class=\"pb-2\"\n                                                >\n                                                    Referencia\n                                                </th>\n                                                <th\n                                                    v-if=\"\n                                                        form.payments.length > 0\n                                                    \"\n                                                    class=\"pb-2\"\n                                                >\n                                                    Monto\n                                                </th>\n                                                <th width=\"15%\">\n                                                    <a\n                                                        href=\"#\"\n                                                        @click.prevent=\"\n                                                            clickAddPayment\n                                                        \"\n                                                        class=\"text-center font-weight-bold text-info\"\n                                                        >[+ Agregar]</a\n                                                    >\n                                                </th>\n                                            </tr>\n                                        </thead>\n                                        <tbody>\n                                            <tr\n                                                v-for=\"(row,\n                                                index) in form.payments\"\n                                                :key=\"index\"\n                                            >\n                                                <td>\n                                                    <div\n                                                        class=\"form-group mb-2 mr-2\"\n                                                    >\n                                                        <el-select\n                                                            v-model=\"\n                                                                row.payment_method_type_id\n                                                            \"\n                                                        >\n                                                            <el-option\n                                                                v-for=\"option in payment_method_types\"\n                                                                :key=\"option.id\"\n                                                                :value=\"\n                                                                    option.id\n                                                                \"\n                                                                :label=\"\n                                                                    option.description\n                                                                \"\n                                                            ></el-option>\n                                                        </el-select>\n                                                    </div>\n                                                </td>\n                                                <td>\n                                                    <div\n                                                        class=\"form-group mb-2 mr-2\"\n                                                    >\n                                                        <el-select\n                                                            v-model=\"\n                                                                row.payment_destination_id\n                                                            \"\n                                                            filterable\n                                                        >\n                                                            <el-option\n                                                                v-for=\"option in payment_destinations\"\n                                                                :key=\"option.id\"\n                                                                :value=\"\n                                                                    option.id\n                                                                \"\n                                                                :label=\"\n                                                                    option.description\n                                                                \"\n                                                            ></el-option>\n                                                        </el-select>\n                                                    </div>\n                                                </td>\n                                                <td>\n                                                    <div\n                                                        class=\"form-group mb-2 mr-2\"\n                                                    >\n                                                        <el-input\n                                                            v-model=\"\n                                                                row.reference\n                                                            \"\n                                                        ></el-input>\n                                                    </div>\n                                                </td>\n                                                <td>\n                                                    <div\n                                                        class=\"form-group mb-2 mr-2\"\n                                                    >\n                                                        <el-input\n                                                            v-model=\"\n                                                                row.payment\n                                                            \"\n                                                        ></el-input>\n                                                    </div>\n                                                </td>\n                                                <td\n                                                    class=\"series-table-actions text-center\"\n                                                >\n                                                    <button\n                                                        type=\"button\"\n                                                        class=\"btn waves-effect waves-light btn-xs btn-danger\"\n                                                        @click.prevent=\"\n                                                            clickCancel(index)\n                                                        \"\n                                                    >\n                                                        <i\n                                                            class=\"fa fa-trash\"\n                                                        ></i>\n                                                    </button>\n                                                </td>\n                                                <br />\n                                            </tr>\n                                        </tbody>\n                                    </table>\n                                </div>\n                            </div>\n                            <!-- final pago -->\n                        </div>\n                    </div>\n\n                    <div\n                        class=\"form-actions footer-card-default text-right mt-4 pl-4 pr-4 pb-3 pt-3\"\n                    >\n                        <el-button\n                            class=\"second-buton btn btn-default second-buton-default\"\n                            @click.prevent=\"close()\"\n                            >Cancelar</el-button\n                        >\n                        <el-button\n                            class=\"submit btn btn-primary btn-submit-default\"\n                            type=\"primary\"\n                            native-type=\"submit\"\n                            :loading=\"loading_submit\"\n                            v-if=\"form.items.length > 0\"\n                            >Generar\n                        </el-button>\n                    </div>\n                </form>\n            </div>\n        </div>\n\n        <contract-form-item\n            :showDialog.sync=\"showDialogAddItem\"\n            :currency-type-id-active=\"form.currency_type_id\"\n            :exchange-rate-sale=\"form.exchange_rate_sale\"\n            :percentage-igv=\"percentage_igv\"\n            :permissionEditItemPrices=\"authUser.permission_edit_item_prices\"\n            @add=\"addRow\"\n        ></contract-form-item>\n\n        <person-form\n            :showDialog.sync=\"showDialogNewPerson\"\n            type=\"customers\"\n            :external=\"true\"\n            :input_person=\"input_person\"\n            :document_type_id=\"form.document_type_id\"\n        ></person-form>\n\n        <contract-options-pdf\n            :showDialog.sync=\"showDialogOptionsPdf\"\n            :contractNewId=\"contractNewId\"\n            :showClose=\"true\"\n        ></contract-options-pdf>\n\n        <terms-condition\n            :showDialog.sync=\"showDialogTermsCondition\"\n            :form=\"form\"\n            :showClose=\"false\"\n        ></terms-condition>\n    </div>\n</template>\n<style>\n.toggle-button {\n    position: fixed;\n    top: 35%;\n    right: -105px;\n    transform: translateY(-50%) rotate(-90deg);\n    transform-origin: center;\n    background-color: rgba(115, 183, 255, 0.6);\n    color: white;\n    padding: 5px 10px;\n    cursor: pointer;\n    border-radius: 5px;\n    z-index: 1;\n    transition: all 0.3s ease-in-out;\n    font-weight: 400;\n    font-size: 16px;\n    line-height: 1;\n    display: block;\n    height: auto;\n    width: 230px !important;\n    border: none;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    text-align: center;\n}\n.toggle-button:hover {\n    background-color: rgba(0, 123, 255, 0.8);\n    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);\n}\n.toggle-button.shift {\n    right: 300px !important;\n    background-color: rgba(0, 123, 255, 0.8);\n    z-index: 1023;\n}\n.additional-information {\n    position: fixed;\n    display: flex;\n    flex-direction: column;\n    padding-left: 20px;\n    padding-right: 20px;\n    top: 0;\n    right: -100%;\n    height: 100%;\n    width: 400px;\n    background-color: #f9f9f9;\n    box-shadow: -2px 0 5px rgba(0, 0, 0, 0.1);\n    transition: right 0.3s ease-in-out;\n    overflow-y: auto;\n    z-index: 1022;\n}\n.additional-information.show {\n    right: 0;\n}\n.content-opacity {\n    position: relative;\n}\n.content-opacity::after {\n    content: \"\";\n    position: fixed;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    background-color: rgba(0, 0, 0, 0.5);\n    z-index: 1021;\n}\n@media only screen and (max-width: 920px) {\n    .head-notes .dates {\n        display: flex;\n        flex-direction: column;\n    }\n    .head-notes .dates .issue-date,\n    .head-notes .dates .expiration-date,\n    .head-notes .dates .delivery-date {\n        width: 90% !important;\n    }\n}\n@media only screen and (max-width: 768px) {\n    header .head-notes {\n        display: flex;\n        flex-direction: column;\n        justify-content: start;\n    }\n    .head-notes .dates {\n        margin-left: 0px !important;\n    }\n    .head-notes .dates .issue-date,\n    .head-notes .dates .expiration-date,\n    .head-notes .dates .delivery-date {\n        width: 100% !important;\n    }\n}\n@media only screen and (max-width: 460px) {\n    .additional-information {\n        width: 80%;\n    }\n    .toggle-button.shift {\n        right: 58% !important;\n    }\n}\n</style>\n<script>\nimport TermsCondition from \"./partials/terms_condition.vue\";\nimport ContractFormItem from \"./partials/item.vue\";\nimport PersonForm from \"@views/persons/form.vue\";\nimport ContractOptionsPdf from \"./partials/options_pdf.vue\";\nimport { functions, exchangeRate } from \"@mixins/functions\";\nimport { calculateRowItem, showNamePdfOfDescription } from \"@helpers/functions\";\nimport Logo from \"@views/companies/logo.vue\";\n\nexport default {\n    props: [\"typeUser\", \"quotationId\", \"id\", \"showPayments\", \"authUser\"],\n    components: {\n        ContractFormItem,\n        PersonForm,\n        ContractOptionsPdf,\n        Logo,\n        TermsCondition\n    },\n    computed: {\n        getCurrentLogo() {\n            const isDarkMode = document.documentElement.classList.contains('dark');\n        \n            if (isDarkMode && this.company.logo_dark) {\n                return `/storage/uploads/logos/${this.company.logo_dark}`;\n            }\n            if (this.company.logo) {\n                return `/storage/uploads/logos/${this.company.logo}`;\n            }\n            return '';\n        }\n    },\n    mixins: [functions, exchangeRate],\n    data() {\n        return {\n            isVisible: false,\n            sellers: [],\n            resource: \"contracts\",\n            input_person: {},\n            showDialogTermsCondition: false,\n            showDialogAddItem: false,\n            showDialogNewPerson: false,\n            showDialogOptionsPdf: false,\n            loading_submit: false,\n            loading_form: false,\n            errors: {},\n            form: {},\n            currency_types: [],\n            discount_types: [],\n            charges_types: [],\n            all_customers: [],\n            payment_method_types: [],\n            customers: [],\n            recordId: null,\n            company: null,\n            establishments: [],\n            establishment: null,\n            quotation: {},\n            currency_type: {},\n            contractNewId: null,\n            payment_destinations: [],\n            configuration: {},\n            activePanel: 0,\n            loading_search: false\n        };\n    },\n    async created() {\n        // console.log(this.showPayments)\n        await this.initForm();\n        await this.$http.get(`/${this.resource}/tables`).then(response => {\n            const data = response.data;\n            this.currency_types = data.currency_types;\n            this.establishments = data.establishments;\n            this.all_customers = data.customers;\n            this.discount_types = data.discount_types;\n            this.charges_types = data.charges_types;\n            this.company = data.company;\n            this.form.currency_type_id =\n                this.currency_types.length > 0\n                    ? this.currency_types[0].id\n                    : null;\n            this.form.establishment_id =\n                this.establishments.length > 0\n                    ? this.establishments[0].id\n                    : null;\n            this.payment_method_types = data.payment_method_types;\n            this.payment_destinations = data.payment_destinations;\n            this.configuration = data.configuration;\n            this.sellers = data.sellers;\n\n            this.changeEstablishment();\n            this.changeDateOfIssue();\n            this.changeCurrencyType();\n            this.allCustomers();\n            this.selectDestinationSale();\n        });\n        await this.getPercentageIgv();\n        this.loading_form = true;\n        this.$eventHub.$on(\"reloadDataPersons\", customer_id => {\n            this.reloadDataCustomers(customer_id);\n        });\n\n        this.$eventHub.$on(\"initInputPerson\", () => {\n            this.initInputPerson();\n        });\n\n        await this.isUpdate();\n        await this.generateFromQuotation();\n    },\n    methods: {\n        toggleInformation() {\n            this.isVisible = !this.isVisible;\n        },\n        setDescriptionOfItem(item) {\n            return showNamePdfOfDescription(\n                item,\n                this.configuration.show_pdf_name\n            );\n        },\n        selectDestinationSale() {\n            if (\n                this.configuration.destination_sale &&\n                this.payment_destinations.length > 0 &&\n                this.showPayments\n            ) {\n                let cash = _.find(this.payment_destinations, { id: \"cash\" });\n                this.form.payments[0].payment_destination_id = cash\n                    ? cash.id\n                    : this.payment_destinations[0].id;\n            }\n        },\n        getPaymentDestinationId() {\n            if (\n                this.configuration.destination_sale &&\n                this.payment_destinations.length > 0\n            ) {\n                let cash = _.find(this.payment_destinations, { id: \"cash\" });\n\n                return cash ? cash.id : this.payment_destinations[0].id;\n            }\n\n            return null;\n        },\n        async generateFromQuotation() {\n            if (this.quotationId) {\n                await this.$http\n                    .get(`/quotations/record/${this.quotationId}`)\n                    .then(response => {\n                        this.quotation = response.data.data.quotation;\n                    });\n\n                this.reloadDataCustomers(this.quotation.customer_id);\n                this.form.establishment_id = this.quotation.establishment_id;\n                this.form.customer_id = this.quotation.customer_id;\n                this.form.currency_type_id = this.quotation.currency_type_id;\n                this.form.items = this.quotation.items;\n                // this.form.payments = this.quotation.payments\n                this.form.total_exportation = this.quotation.total_exportation;\n                this.form.total_free = this.quotation.total_free;\n                this.form.total_taxed = this.quotation.total_taxed;\n                this.form.total_unaffected = this.quotation.total_unaffected;\n                this.form.total_exonerated = this.quotation.total_exonerated;\n                this.form.total_igv = this.quotation.total_igv;\n                this.form.total_taxes = this.quotation.total_taxes;\n                this.form.total_value = this.quotation.total_value;\n                this.form.total = this.quotation.total;\n                this.form.quotation_id = this.quotation.id;\n                // console.log(this.form)\n                this.form.account_number = this.quotation.account_number;\n                this.form.description = this.quotation.description;\n                this.form.payment_method_type_id = this.quotation.payment_method_type_id;\n                this.form.shipping_address = this.quotation.shipping_address;\n            }\n        },\n        async isUpdate() {\n            if (this.id) {\n                await this.$http\n                    .get(`/${this.resource}/record/${this.id}`)\n                    .then(response => {\n                        this.form = response.data.data.contract;\n                        this.reloadDataCustomers(this.form.customer_id);\n                    });\n            }\n        },\n        changeTermsCondition() {\n            if (this.form.active_terms_condition) {\n                this.showDialogTermsCondition = true;\n            } else {\n                this.form.terms_condition = null;\n            }\n        },\n        clickAddPayment() {\n            this.form.payments.push({\n                id: null,\n                contract_id: null,\n                date_of_payment: moment().format(\"YYYY-MM-DD\"),\n                payment_method_type_id: \"01\",\n                reference: null,\n                payment_destination_id: this.getPaymentDestinationId(),\n                payment: 0\n            });\n            this.showPayments = true; // Asegurar que la tabla se muestre\n        },\n        clickCancel(index) {\n            this.form.payments.splice(index, 1);\n        },\n        getFormatUnitPriceRow(unit_price) {\n            return _.round(unit_price, 6);\n            // return unit_price.toFixed(6)\n        },\n        async changePaymentMethodType(flag_submit = true) {\n            let payment_method_type = await _.find(this.payment_method_types, {\n                id: this.form.payment_method_type_id\n            });\n            if (payment_method_type) {\n                if (payment_method_type.number_days) {\n                    this.form.date_of_issue = moment()\n                        .add(payment_method_type.number_days, \"days\")\n                        .format(\"YYYY-MM-DD\");\n                    this.changeDateOfIssue();\n                }\n                // else{\n                //     if(flag_submit){\n                //         this.form.date_of_issue = moment().format('YYYY-MM-DD')\n                //         this.changeDateOfIssue()\n                //     }\n                // }\n            }\n        },\n        searchRemoteCustomers(input) {\n            if (input.length > 0) {\n                this.loading_search = true;\n                let parameters = `input=${input}`;\n\n                this.$http\n                    .get(`/${this.resource}/search/customers?${parameters}`)\n                    .then(response => {\n                        this.customers = response.data.customers;\n                        this.loading_search = false;\n                        /* if(this.customers.length == 0){this.allCustomers()} */\n                        this.input_person.number =\n                            this.customers.length == 0 ? input : null;\n                    });\n            } else {\n                this.allCustomers();\n                this.input_person.number = null;\n            }\n        },\n        initForm() {\n            this.errors = {};\n            this.form = {\n                description: \"\",\n                prefix: \"CNT\",\n                establishment_id: null,\n                date_of_issue: moment().format(\"YYYY-MM-DD\"),\n                time_of_issue: moment().format(\"HH:mm:ss\"),\n                customer_id: null,\n                currency_type_id: null,\n                purchase_order: null,\n                exchange_rate_sale: 0,\n                total_prepayment: 0,\n                total_charge: 0,\n                total_discount: 0,\n                total_exportation: 0,\n                total_free: 0,\n                total_taxed: 0,\n                total_unaffected: 0,\n                total_exonerated: 0,\n                total_igv: 0,\n                total_base_isc: 0,\n                total_isc: 0,\n                total_base_other_taxes: 0,\n                total_other_taxes: 0,\n                total_taxes: 0,\n                total_value: 0,\n                total: 0,\n                operation_type_id: null,\n                date_of_due: null,\n                delivery_date: null,\n                items: [],\n                charges: [],\n                discounts: [],\n                attributes: [],\n                guides: [],\n                payment_method_type_id: \"10\",\n                additional_information: null,\n                shipping_address: null,\n                account_number: null,\n                terms_condition: null,\n                active_terms_condition: false,\n                actions: {\n                    format_pdf: \"a4\"\n                },\n                payments: [],\n                quotation_id: null\n            };\n\n            if (this.showPayments) {\n                this.clickAddPayment();\n            }\n        },\n        resetForm() {\n            this.activePanel = 0;\n            this.initForm();\n            this.form.currency_type_id =\n                this.currency_types.length > 0\n                    ? this.currency_types[0].id\n                    : null;\n            this.form.establishment_id =\n                this.establishments.length > 0\n                    ? this.establishments[0].id\n                    : null;\n            this.changeEstablishment();\n            this.changeDateOfIssue();\n            this.changeCurrencyType();\n            this.allCustomers();\n        },\n        changeEstablishment() {\n            this.establishment = _.find(this.establishments, {\n                id: this.form.establishment_id\n            });\n        },\n        cleanCustomer() {\n            this.form.customer_id = null;\n        },\n        async changeDateOfIssue() {\n            // this.form.date_of_due = this.form.date_of_issue > this.form.date_of_due ? this.form.date_of_issue:null\n            await this.searchExchangeRateByDate(this.form.date_of_issue).then(\n                response => {\n                    this.form.exchange_rate_sale = response;\n                }\n            );\n            await this.getPercentageIgv();\n            this.changeCurrencyType();\n        },\n        allCustomers() {\n            this.customers = this.all_customers;\n        },\n        addRow(row) {\n            this.form.items.push(JSON.parse(JSON.stringify(row)));\n\n            this.calculateTotal();\n        },\n        clickRemoveItem(index) {\n            this.form.items.splice(index, 1);\n            this.calculateTotal();\n        },\n        changeCurrencyType() {\n            this.currency_type = _.find(this.currency_types, {\n                id: this.form.currency_type_id\n            });\n            let items = [];\n            this.form.items.forEach(row => {\n                items.push(\n                    calculateRowItem(\n                        row,\n                        this.form.currency_type_id,\n                        this.form.exchange_rate_sale,\n                        this.percentage_igv\n                    )\n                );\n            });\n            this.form.items = items;\n            this.calculateTotal();\n        },\n        calculateTotal() {\n            let total_discount = 0;\n            let total_charge = 0;\n            let total_exportation = 0;\n            let total_taxed = 0;\n            let total_exonerated = 0;\n            let total_unaffected = 0;\n            let total_free = 0;\n            let total_igv = 0;\n            let total_value = 0;\n            let total = 0;\n            this.form.items.forEach(row => {\n                total_discount += parseFloat(row.total_discount);\n                total_charge += parseFloat(row.total_charge);\n\n                if (row.affectation_igv_type_id === \"10\") {\n                    total_taxed += parseFloat(row.total_value);\n                }\n                if (row.affectation_igv_type_id === \"20\") {\n                    total_exonerated += parseFloat(row.total_value);\n                }\n                if (row.affectation_igv_type_id === \"30\") {\n                    total_unaffected += parseFloat(row.total_value);\n                }\n                if (row.affectation_igv_type_id === \"40\") {\n                    total_exportation += parseFloat(row.total_value);\n                }\n                if (\n                    [\"10\", \"20\", \"30\", \"40\"].indexOf(\n                        row.affectation_igv_type_id\n                    ) < 0\n                ) {\n                    total_free += parseFloat(row.total_value);\n                }\n                if (\n                    [\"10\", \"20\", \"30\", \"40\"].indexOf(\n                        row.affectation_igv_type_id\n                    ) > -1\n                ) {\n                    total_igv += parseFloat(row.total_igv);\n                    total += parseFloat(row.total);\n                }\n                total_value += parseFloat(row.total_value);\n            });\n\n            this.form.total_exportation = _.round(total_exportation, 2);\n            this.form.total_taxed = _.round(total_taxed, 2);\n            this.form.total_exonerated = _.round(total_exonerated, 2);\n            this.form.total_unaffected = _.round(total_unaffected, 2);\n            this.form.total_free = _.round(total_free, 2);\n            this.form.total_igv = _.round(total_igv, 2);\n            this.form.total_value = _.round(total_value, 2);\n            this.form.total_taxes = _.round(total_igv, 2);\n            this.form.total = _.round(total, 2);\n\n            this.showPayments = this.form.items.length > 0;\n        },\n        validate_payments() {\n            //eliminando items de pagos\n            for (let index = 0; index < this.form.payments.length; index++) {\n                if (parseFloat(this.form.payments[index].payment) === 0)\n                    this.form.payments.splice(index, 1);\n            }\n\n            let error_by_item = 0;\n            let acum_total = 0;\n\n            this.form.payments.forEach(item => {\n                acum_total += parseFloat(item.payment);\n                if (item.payment <= 0 || item.payment == null) error_by_item++;\n            });\n\n            return {\n                error_by_item: error_by_item,\n                acum_total: acum_total\n            };\n        },\n        async submit() {\n            let validate = await this.validate_payments();\n            if (\n                validate.acum_total > parseFloat(this.form.total) ||\n                validate.error_by_item > 0\n            ) {\n                return this.$message.error(\n                    \"Los montos ingresados superan al monto a pagar o son incorrectos\"\n                );\n            }\n\n            if (this.form.date_of_issue > this.form.date_of_due)\n                return this.$message.error(\n                    \"La fecha de emisión no puede ser posterior a la de vencimiento\"\n                );\n\n            if (this.form.date_of_issue > this.form.delivery_date)\n                return this.$message.error(\n                    \"La fecha de emisión no puede ser posterior a la de entrega\"\n                );\n\n            this.loading_submit = true;\n            // await this.changePaymentMethodType(false)\n            await this.$http\n                .post(`/${this.resource}`, this.form)\n                .then(response => {\n                    if (response.data.success) {\n                        this.resetForm();\n                        this.contractNewId = response.data.data.id;\n\n                        // console.log(this.quotationId, this.id)\n\n                        if (this.quotationId) {\n                            if (this.showPayments) {\n                                this.$http\n                                    .get(\n                                        `/quotations/changed/${\n                                            this.quotationId\n                                        }`\n                                    )\n                                    .then(() => {\n                                        this.$eventHub.$emit(\"reloadData\");\n                                    });\n                            }\n\n                            this.$message.success(\n                                `El contrato ${\n                                    response.data.data.number_full\n                                } fue generado`\n                            );\n                            this.close();\n                        } else {\n                            this.showDialogOptionsPdf = true;\n                            this.isUpdate();\n                        }\n                    } else {\n                        this.$message.error(response.data.message);\n                    }\n                })\n                .catch(error => {\n                    if (error.response.status === 422) {\n                        this.errors = error.response.data;\n                    } else {\n                        this.$message.error(error.response.data.message);\n                    }\n                })\n                .then(() => {\n                    this.loading_submit = false;\n                });\n        },\n        close() {\n            location.href = \"/\" + this.resource;\n        },\n        reloadDataCustomers(customer_id) {\n            this.$http\n                .get(`/${this.resource}/search/customer/${customer_id}`)\n                .then(response => {\n                    this.customers = response.data.customers;\n                    this.form.customer_id = customer_id;\n                });\n        },\n        keyupCustomer() {\n            if (this.input_person.number) {\n                if (!isNaN(parseInt(this.input_person.number))) {\n                    switch (this.input_person.number.length) {\n                        case 8:\n                            this.input_person.identity_document_type_id = \"1\";\n                            this.showDialogNewPerson = true;\n                            break;\n\n                        case 11:\n                            this.input_person.identity_document_type_id = \"6\";\n                            this.showDialogNewPerson = true;\n                            break;\n                        default:\n                            this.input_person.identity_document_type_id = \"6\";\n                            this.showDialogNewPerson = true;\n                            break;\n                    }\n                }\n            }\n        },\n        initInputPerson() {\n            this.input_person = {\n                number: null,\n                identity_document_type_id: null\n            };\n        }\n    }\n};\n</script>\n"],"sourceRoot":""}]);
