___CSS_LOADER_EXPORT___.push([module.id, "\n.el-select-dropdown {\n    margin-right: 5% !important;\n    max-width: 80% !important;\n}\n.product-search-model .el-tooltip {\n    position: absolute;\n    right: 7px;\n    top: 46px;\n    transform: translateY(-50%);\n    z-index: 10;\n    height: 32px;\n    border-top-right-radius: 8px;\n    border-bottom-right-radius: 8px;\n}\n.more-width-input input.el-input__inner {\n    margin-left: -1px !important;\n}\n", "",{"version":3,"sources":["webpack://./modules/Sale/Resources/assets/js/views/sale_opportunities/partials/item.vue"],"names":[],"mappings":";AAiSA;IACA,2BAAA;IACA,yBAAA;AACA;AACA;IACA,kBAAA;IACA,UAAA;IACA,SAAA;IAEA,2BAAA;IACA,WAAA;IACA,YAAA;IACA,4BAAA;IACA,+BAAA;AACA;AACA;IACA,4BAAA;AACA","sourcesContent":["<template>\n    <el-dialog\n        :close-on-click-modal=\"false\"\n        :title=\"titleDialog\"\n        :visible=\"showDialog\"\n        top=\"7vh\"\n        @close=\"close\"\n        @open=\"create\"\n    >\n        <form autocomplete=\"off\" @submit.prevent=\"clickAddItem\">\n            <div class=\"form-body\">\n                <div class=\"row\">\n                    <div\n                        class=\"col-md-7 col-lg-7 col-xl-7 col-sm-7 product-search-model\"\n                    >\n                        <el-tooltip\n                            slot=\"append\"\n                            class=\"item\"\n                            content=\"Ver Stock del Producto\"\n                            effect=\"dark\"\n                            placement=\"bottom\"\n                        >\n                            <el-button @click.prevent=\"clickWarehouseDetail()\"\n                                ><i class=\"fa fa-search\"></i>\n                            </el-button>\n                        </el-tooltip>\n                        <div\n                            id=\"custom-select\"\n                            :class=\"{ 'has-danger': errors.item_id }\"\n                            class=\"form-group more-width-input\"\n                        >\n                            <label class=\"control-label\">\n                                Producto/Servicio\n                                <a\n                                    href=\"#\"\n                                    @click.prevent=\"showDialogNewItem = true\"\n                                    >[+ Nuevo]</a\n                                >\n                            </label>\n\n                            <!-- <el-select v-model=\"form.item_id\" @change=\"changeItem\" filterable  ref=\"selectSearchNormal\" @focus=\"focusSelectItem\">\n                                <el-option v-for=\"option in items\" :key=\"option.id\" :value=\"option.id\" :label=\"option.full_description\"></el-option>\n                            </el-select> -->\n\n                            <template id=\"select-append\">\n                                <el-input id=\"custom-input\" class=\"input-search-product\">\n                                    <el-select\n                                        id=\"select-width\"\n                                        ref=\"selectSearchNormal\"\n                                        slot=\"prepend\"\n                                        v-model=\"form.item_id\"\n                                        :loading=\"loading_search\"\n                                        :remote-method=\"searchRemoteItems\"\n                                        filterable\n                                        placeholder=\"Buscar\"\n                                        popper-class=\"el-select-items\"\n                                        remote\n                                        @change=\"changeItem\"\n                                        @focus=\"focusSelectItem\"\n                                    >\n                                        <el-tooltip\n                                            v-for=\"option in items\"\n                                            :key=\"option.id\"\n                                            placement=\"left\"\n                                        >\n                                            <div\n                                                slot=\"content\"\n                                                v-html=\"\n                                                    ItemSlotTooltipView(option)\n                                                \"\n                                            ></div>\n                                            <el-option\n                                                :label=\"\n                                                    ItemOptionDescriptionView(\n                                                        option\n                                                    )\n                                                \"\n                                                :value=\"option.id\"\n                                            ></el-option>\n                                        </el-tooltip>\n                                    </el-select>\n                                </el-input>\n                            </template>\n\n                            <small\n                                v-if=\"errors.item_id\"\n                                class=\"form-control-feedback\"\n                                v-text=\"errors.item_id[0]\"\n                            ></small>\n                        </div>\n                    </div>\n                    <div class=\"col-md-5\">\n                        <div\n                            :class=\"{\n                                'has-danger': errors.affectation_igv_type_id\n                            }\"\n                            class=\"form-group\"\n                        >\n                            <label class=\"control-label\">Afectación Igv</label>\n                            <el-select\n                                v-model=\"form.affectation_igv_type_id\"\n                                :disabled=\"!change_affectation_igv_type_id\"\n                                filterable\n                            >\n                                <el-option\n                                    v-for=\"option in affectation_igv_types\"\n                                    :key=\"option.id\"\n                                    :label=\"option.description\"\n                                    :value=\"option.id\"\n                                ></el-option>\n                            </el-select>\n                            <el-checkbox\n                                v-model=\"change_affectation_igv_type_id\"\n                            >\n                                Editar\n                            </el-checkbox>\n                            <small\n                                v-if=\"errors.affectation_igv_type_id\"\n                                class=\"form-control-feedback\"\n                                v-text=\"errors.affectation_igv_type_id[0]\"\n                            ></small>\n                        </div>\n                    </div>\n                    <div class=\"col-md-3\">\n                        <div\n                            :class=\"{ 'has-danger': errors.quantity }\"\n                            class=\"form-group\"\n                        >\n                            <label class=\"control-label\">Cantidad</label>\n                            <el-input-number\n                                v-model=\"form.quantity\"\n                                :disabled=\"form.item.calculate_quantity\"\n                                :min=\"0.01\"\n                            ></el-input-number>\n                            <small\n                                v-if=\"errors.quantity\"\n                                class=\"form-control-feedback\"\n                                v-text=\"errors.quantity[0]\"\n                            ></small>\n                        </div>\n                    </div>\n                    <div class=\"col-md-3\">\n                        <div\n                            :class=\"{ 'has-danger': errors.unit_price }\"\n                            class=\"form-group\"\n                        >\n                            <label class=\"control-label\">Precio Unitario</label>\n                            <el-input\n                                v-model=\"form.unit_price\"\n                                class=\"currency-container\"\n                                :disabled=\"\n                                    !hasPermissionEditItemPrices(\n                                        permissionEditItemPrices\n                                    )\n                                \"\n                                @input=\"calculateQuantity\"\n                            >\n                                <template\n                                    v-if=\"form.item.currency_type_symbol\"\n                                    slot=\"prepend\"\n                                    >{{ form.item.currency_type_symbol }}\n                                </template>\n                            </el-input>\n                            <small\n                                v-if=\"errors.unit_price\"\n                                class=\"form-control-feedback\"\n                                v-text=\"errors.unit_price[0]\"\n                            ></small>\n                        </div>\n                    </div>\n                    <div v-if=\"item_unit_types.length > 0\" class=\"col-md-12\">\n                        <div class=\"table-responsive\" style=\"margin:3px\">\n                            <h3>Lista de Precios</h3>\n                            <table class=\"table\">\n                                <thead>\n                                    <tr>\n                                        <th class=\"text-center\">Unidad</th>\n                                        <th class=\"text-center\">Descripción</th>\n                                        <th class=\"text-center\">Factor</th>\n                                        <th class=\"text-center\">Precio 1</th>\n                                        <th class=\"text-center\">Precio 2</th>\n                                        <th class=\"text-center\">Precio 3</th>\n                                        <th class=\"text-center\">\n                                            Precio Default\n                                        </th>\n                                        <th></th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <tr\n                                        v-for=\"(row, index) in item_unit_types\"\n                                        :key=\"index\"\n                                    >\n                                        <td class=\"text-center\">\n                                            {{ row.unit_type_id }}\n                                        </td>\n                                        <td class=\"text-center\">\n                                            {{ row.description }}\n                                        </td>\n                                        <td class=\"text-center\">\n                                            {{ row.quantity_unit }}\n                                        </td>\n                                        <td class=\"text-center\">\n                                            {{ row.price1 }}\n                                        </td>\n                                        <td class=\"text-center\">\n                                            {{ row.price2 }}\n                                        </td>\n                                        <td class=\"text-center\">\n                                            {{ row.price3 }}\n                                        </td>\n                                        <td class=\"text-center\">\n                                            Precio {{ row.price_default }}\n                                        </td>\n                                        <td\n                                            class=\"series-table-actions text-right\"\n                                        >\n                                            <button\n                                                class=\"btn waves-effect waves-light btn-xs btn-success\"\n                                                type=\"button\"\n                                                @click.prevent=\"\n                                                    selectedPrice(row)\n                                                \"\n                                            >\n                                                <i class=\"el-icon-check\"></i>\n                                            </button>\n                                        </td>\n                                    </tr>\n                                </tbody>\n                            </table>\n                        </div>\n                    </div>\n                    <div\n                        v-show=\"form.item.calculate_quantity\"\n                        class=\"col-md-3 col-sm-6\"\n                    >\n                        <div\n                            :class=\"{ 'has-danger': errors.total_item }\"\n                            class=\"form-group\"\n                        >\n                            <label class=\"control-label\"\n                                >Total venta producto</label\n                            >\n                            <el-input\n                                ref=\"total_item\"\n                                v-model=\"total_item\"\n                                :min=\"0.01\"\n                                @input=\"calculateQuantity\"\n                            >\n                                <template\n                                    v-if=\"form.item.currency_type_symbol\"\n                                    slot=\"prepend\"\n                                    >{{ form.item.currency_type_symbol }}\n                                </template>\n                            </el-input>\n                            <small\n                                v-if=\"errors.total_item\"\n                                class=\"form-control-feedback\"\n                                v-text=\"errors.total_item[0]\"\n                            ></small>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class=\"form-actions text-right pt-2\">\n                <el-button class=\"second-buton\" @click.prevent=\"close()\"\n                    >Cerrar</el-button\n                >\n                <el-button\n                    v-if=\"form.item_id\"\n                    native-type=\"submit\"\n                    type=\"primary\"\n                    >Agregar\n                </el-button>\n            </div>\n        </form>\n        <item-form\n            :external=\"true\"\n            :showDialog.sync=\"showDialogNewItem\"\n        ></item-form>\n\n        <warehouses-detail\n            :showDialog.sync=\"showWarehousesDetail\"\n            :warehouses=\"warehousesDetail\"\n        >\n        </warehouses-detail>\n    </el-dialog>\n</template>\n<style>\n.el-select-dropdown {\n    margin-right: 5% !important;\n    max-width: 80% !important;\n}\n.product-search-model .el-tooltip {\n    position: absolute;\n    right: 7px;\n    top: 46px;\n    -webkit-transform: translateY(-50%);\n    transform: translateY(-50%);\n    z-index: 10;\n    height: 32px;\n    border-top-right-radius: 8px;\n    border-bottom-right-radius: 8px;\n}\n.more-width-input input.el-input__inner {\n    margin-left: -1px !important;\n}\n</style>\n<script>\nimport itemForm from \"@views/items/form.vue\";\nimport { calculateRowItem } from \"@helpers/functions\";\nimport WarehousesDetail from \"./warehouses.vue\";\n\nimport ClassicEditor from \"@ckeditor/ckeditor5-build-classic\";\nimport VueCkeditor from \"vue-ckeditor5\";\nimport { mapActions, mapState } from \"vuex/dist/vuex.mjs\";\nimport {\n    ItemOptionDescription,\n    ItemSlotTooltip\n} from \"../../../../../../../../resources/js/helpers/modal_item\";\nimport { checkPermissionEditPrices } from \"@mixins/check-permission-edit-prices\";\n\nexport default {\n    props: [\n        \"showDialog\",\n        \"currencyTypeIdActive\",\n        \"exchangeRateSale\",\n        \"percentageIgv\",\n        \"permissionEditItemPrices\"\n    ],\n    components: {\n        itemForm,\n        WarehousesDetail,\n        \"vue-ckeditor\": VueCkeditor.component\n    },\n    mixins: [checkPermissionEditPrices],\n    data() {\n        return {\n            can_add_new_product: false,\n            loading_search: false,\n            titleAction: \"\",\n            is_client: false,\n            titleDialog: \"Agregar Producto o Servicio\",\n            resource: \"sale-opportunities\",\n            showDialogNewItem: false,\n            has_list_prices: false,\n            errors: {},\n            form: {},\n            all_items: [],\n            items: [],\n            operation_types: [],\n            all_affectation_igv_types: [],\n            aux_items: [],\n            affectation_igv_types: [],\n            system_isc_types: [],\n            discount_types: [],\n            charge_types: [],\n            attribute_types: [],\n            use_price: 1,\n            change_affectation_igv_type_id: false,\n            activePanel: 0,\n            total_item: 0,\n            item_unit_types: [],\n            item_unit_type: {},\n            showWarehousesDetail: false,\n            warehousesDetail: [],\n            showListStock: false,\n            search_item_by_barcode: false,\n            isUpdateWarehouseId: null,\n            showDialogLots: false,\n            showDialogSelectLots: false,\n            lots: [],\n            editors: {\n                classic: ClassicEditor\n            }\n        };\n    },\n    created() {\n        this.loadConfiguration();\n        // this.$store.commit('setConfiguration', this.configuration)\n        this.initForm();\n        this.$http.get(`/${this.resource}/item/tables`).then(response => {\n            this.items = response.data.items;\n            this.affectation_igv_types = response.data.affectation_igv_types;\n            // this.filterItems()\n        });\n\n        this.$eventHub.$on(\"reloadDataItems\", item_id => {\n            this.reloadDataItems(item_id);\n        });\n    },\n    computed: {\n        ...mapState([\"config\"])\n    },\n    methods: {\n        ...mapActions([\"loadConfiguration\"]),\n\n        hasAttributes() {\n            if (\n                this.form.item !== undefined &&\n                this.form.item.attributes !== undefined &&\n                this.form.item.attributes !== null &&\n                this.form.item.attributes.length > 0\n            ) {\n                return true;\n            }\n\n            return false;\n        },\n        ItemSlotTooltipView(item) {\n            return ItemSlotTooltip(item);\n        },\n        ItemOptionDescriptionView(item) {\n            return ItemOptionDescription(item);\n        },\n\n        async searchRemoteItems(input) {\n            if (input.length > 2) {\n                this.loading_search = true;\n                const params = {\n                    input: input,\n                    search_by_barcode: this.search_item_by_barcode ? 1 : 0\n                };\n                await this.$http\n                    .get(`/${this.resource}/search-items/`, { params })\n                    .then(response => {\n                        this.items = response.data.items;\n                        this.loading_search = false;\n                        this.enabledSearchItemsBarcode();\n                        this.enabledSearchItemBySeries();\n                        if (this.items.length == 0) {\n                            this.filterItems();\n                        }\n                    });\n            } else {\n                await this.filterItems();\n            }\n        },\n        filterItems() {\n            this.items = this.all_items;\n        },\n\n        enabledSearchItemsBarcode() {\n            if (this.search_item_by_barcode) {\n                this.$refs.selectBarcode.$data.selectedLabel = \"\";\n                if (this.items.length == 1) {\n                    this.form.item_id = this.items[0].id;\n                    this.$refs.selectBarcode.blur();\n                    this.changeItem();\n                }\n            }\n        },\n        async enabledSearchItemBySeries() {\n            if (this.config.search_item_by_series && this.items.length == 1) {\n                this.$notify({\n                    title: \"Serie ubicada\",\n                    message: \"Producto añadido!\",\n                    type: \"success\",\n                    duration: 1200\n                });\n                this.form.item_id = this.items[0].id;\n                this.$refs.selectSearchNormal.$data.selectedLabel = \"\";\n\n                await this.changeItem();\n\n                this.lots = await this.form.item.lots.map(lot => {\n                    lot.has_sale = true;\n                });\n\n                await this.clickAddItem();\n\n                this.$refs.selectSearchNormal.$data.selectedLabel = \"\";\n            }\n\n            if (this.config.search_item_by_series && this.items.length == 0) {\n                this.$notify({\n                    title: \"Serie no ubicada\",\n                    message: \"\",\n                    type: \"warning\",\n                    duration: 1200\n                });\n            }\n        },\n\n        filterMethod(query) {\n            let item = _.find(this.items, { internal_id: query });\n\n            if (item) {\n                this.form.item_id = item.id;\n                this.changeItem();\n            }\n        },\n        clickWarehouseDetail() {\n            if (!this.form.item_id) {\n                return this.$message.error(\"Seleccione un item\");\n            }\n\n            let item = _.find(this.items, { id: this.form.item_id });\n\n            this.warehousesDetail = item.warehouses;\n            this.showWarehousesDetail = true;\n        },\n        //filterItems() {\n        // this.items = this.items.filter(item => item.warehouses.length >0)\n        // },\n        initForm() {\n            this.errors = {};\n\n            this.form = {\n                item_id: null,\n                item: {},\n                affectation_igv_type_id: null,\n                affectation_igv_type: {},\n                has_isc: false,\n                system_isc_type_id: null,\n                percentage_isc: 0,\n                suggested_price: 0,\n                quantity: 1,\n                unit_price: 0,\n                charges: [],\n                discounts: [],\n                attributes: [],\n                has_igv: null,\n                item_unit_type_id: null,\n                unit_type_id: null,\n                is_set: false\n            };\n\n            this.total_item = 0;\n            this.item_unit_type = {};\n            this.has_list_prices = false;\n        },\n        close() {\n            this.initForm();\n            this.$emit(\"update:showDialog\", false);\n        },\n        changeItem() {\n            this.getItems();\n            this.form.item = _.find(this.items, { id: this.form.item_id });\n            this.form.unit_price = this.form.item.sale_unit_price;\n\n            this.form.has_igv = this.form.item.has_igv;\n\n            this.form.affectation_igv_type_id = this.form.item.sale_affectation_igv_type_id;\n            this.form.quantity = 1;\n            this.item_unit_types = this.form.item.item_unit_types;\n\n            this.item_unit_types.length > 0\n                ? (this.has_list_prices = true)\n                : (this.has_list_prices = false);\n\n            this.cleanTotalItem();\n        },\n        changePresentation() {\n            let price = 0;\n\n            this.item_unit_type = _.find(this.form.item.item_unit_types, {\n                id: this.form.item_unit_type_id\n            });\n\n            switch (this.item_unit_type.price_default) {\n                case 1:\n                    price = this.item_unit_type.price1;\n                    break;\n                case 2:\n                    price = this.item_unit_type.price2;\n                    break;\n                case 3:\n                    price = this.item_unit_type.price3;\n                    break;\n            }\n\n            this.form.unit_price = price;\n            this.form.item.unit_type_id = this.item_unit_type.unit_type_id;\n        },\n        selectedPrice(row) {\n            let valor = 0;\n            switch (row.price_default) {\n                case 1:\n                    valor = row.price1;\n                    break;\n                case 2:\n                    valor = row.price2;\n                    break;\n                case 3:\n                    valor = row.price3;\n                    break;\n            }\n\n            this.item_unit_type = row;\n            this.form.unit_price = valor;\n            this.form.item.unit_type_id = row.unit_type_id;\n            this.form.item_unit_type_id = row.id;\n        },\n        clickAddItem() {\n            if (this.validateTotalItem().total_item) return;\n\n            // this.form.item.unit_price = this.form.unit_price;\n            let unit_price = this.form.has_igv\n                ? this.form.unit_price\n                : this.form.unit_price * (1 + this.percentageIgv);\n\n            // this.form.item.unit_price = this.form.unit_price\n            this.form.unit_price = unit_price;\n            this.form.item.unit_price = unit_price;\n\n            this.form.item.presentation = this.item_unit_type;\n            this.form.affectation_igv_type = _.find(\n                this.affectation_igv_types,\n                { id: this.form.affectation_igv_type_id }\n            );\n            this.row = calculateRowItem(\n                this.form,\n                this.currencyTypeIdActive,\n                this.exchangeRateSale,\n                this.percentageIgv\n            );\n\n            this.initForm();\n\n            // this.initializeFields()\n            this.$emit(\"add\", this.row);\n            this.setFocusSelectItem();\n        },\n        focusSelectItem() {\n            this.$refs.selectSearchNormal.$el\n                .getElementsByTagName(\"input\")[0]\n                .focus();\n        },\n        setFocusSelectItem() {\n            this.$refs.selectSearchNormal.$el\n                .getElementsByTagName(\"input\")[0]\n                .focus();\n        },\n        cleanTotalItem() {\n            this.total_item = null;\n        },\n        calculateQuantity() {\n            if (this.form.item.calculate_quantity) {\n                this.form.quantity = _.round(\n                    this.total_item / this.form.unit_price,\n                    4\n                );\n            }\n        },\n        getItems() {\n            this.$http.get(`/${this.resource}/item/tables`).then(response => {\n                this.items = response.data.items;\n            });\n        },\n        validateTotalItem() {\n            this.errors = {};\n\n            if (this.form.item.calculate_quantity) {\n                if (this.total_item < 0.01)\n                    this.$set(this.errors, \"total_item\", [\n                        \"total venta producto debe ser mayor a 0\"\n                    ]);\n            }\n\n            return this.errors;\n        },\n        create() {},\n        reloadDataItems(item_id) {\n            this.$http.get(`/${this.resource}/table/items`).then(response => {\n                this.items = response.data;\n                this.form.item_id = item_id;\n                if (item_id) {\n                    this.changeItem();\n                }\n                // this.filterItems()\n            });\n        }\n    }\n};\n</script>\n"],"sourceRoot":""}]);
